// Package server implements the notes HTTP API.
package server

import (
	"encoding/json"
	"errors"
	"io"
	"log/slog"
	"net/http"
	"slices"
	"strings"

	"notes/internal/store"
)

const (
	maxBodyBytes = 16 << 20
	maxLimit     = 100
)

// Server serves the notes API backed by a Store.
type Server struct {
	store *store.Store
	log   *slog.Logger
}

// New returns an http.Handler serving the notes API.
func New(st *store.Store, log *slog.Logger) *Server {
	return &Server{store: st, log: log}
}

// ServeHTTP routes requests. Routing is done by hand so that unknown paths,
// unsupported methods and malformed ids all get JSON error bodies.
func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path
	switch {
	case path == "/health":
		s.route(w, r, map[string]http.HandlerFunc{http.MethodGet: s.health})
	case path == "/notes":
		s.route(w, r, map[string]http.HandlerFunc{
			http.MethodGet:  s.listNotes,
			http.MethodPost: s.createNote,
		})
	case strings.HasPrefix(path, "/notes/") && !strings.Contains(path[len("/notes/"):], "/"):
		s.route(w, r, map[string]http.HandlerFunc{
			http.MethodGet:    s.getNote,
			http.MethodPut:    s.updateNote,
			http.MethodDelete: s.deleteNote,
		})
	case path == "/stats":
		s.route(w, r, map[string]http.HandlerFunc{http.MethodGet: s.stats})
	case path == "/tags":
		s.route(w, r, map[string]http.HandlerFunc{http.MethodGet: s.tags})
	default:
		writeError(w, http.StatusNotFound, "not found")
	}
}

func (s *Server) route(w http.ResponseWriter, r *http.Request, methods map[string]http.HandlerFunc) {
	h, ok := methods[r.Method]
	if !ok {
		allowed := make([]string, 0, len(methods))
		for m := range methods {
			allowed = append(allowed, m)
		}
		slices.Sort(allowed)
		w.Header().Set("Allow", strings.Join(allowed, ", "))
		writeError(w, http.StatusMethodNotAllowed, "method not allowed")
		return
	}
	h(w, r)
}

func (s *Server) health(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	_, _ = io.WriteString(w, "ok")
}

func (s *Server) createNote(w http.ResponseWriter, r *http.Request) {
	in, ok := s.readNoteInput(w, r)
	if !ok {
		return
	}
	n, err := s.store.Create(r.Context(), in.Title, in.Body, in.Tags)
	if err != nil {
		s.internalError(w, r, err)
		return
	}
	writeJSON(w, http.StatusCreated, n)
}

func (s *Server) getNote(w http.ResponseWriter, r *http.Request) {
	id, ok := noteID(w, r)
	if !ok {
		return
	}
	n, err := s.store.Get(r.Context(), id)
	if err != nil {
		s.storeError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, n)
}

func (s *Server) updateNote(w http.ResponseWriter, r *http.Request) {
	id, ok := noteID(w, r)
	if !ok {
		return
	}
	in, ok := s.readNoteInput(w, r)
	if !ok {
		return
	}
	n, err := s.store.Update(r.Context(), id, in.Title, in.Body, in.Tags)
	if err != nil {
		s.storeError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, n)
}

func (s *Server) deleteNote(w http.ResponseWriter, r *http.Request) {
	id, ok := noteID(w, r)
	if !ok {
		return
	}
	if err := s.store.Delete(r.Context(), id); err != nil {
		s.storeError(w, r, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

func (s *Server) listNotes(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	f := store.ListFilter{
		Tag:   q.Get("tag"),
		Query: q.Get("q"),
		Limit: maxLimit,
	}
	if q.Has("limit") {
		n, ok := parseInt(q.Get("limit"))
		if !ok || n < 1 || n > maxLimit {
			writeError(w, http.StatusBadRequest, "limit must be an integer from 1 to 100")
			return
		}
		f.Limit = int(n)
	}
	if q.Has("after") {
		n, ok := parseInt(q.Get("after"))
		if !ok {
			writeError(w, http.StatusBadRequest, "after must be an integer")
			return
		}
		f.After = n
	}
	notes, err := s.store.List(r.Context(), f)
	if err != nil {
		s.internalError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"notes": notes})
}

func (s *Server) stats(w http.ResponseWriter, r *http.Request) {
	total, counts, err := s.store.Stats(r.Context())
	if err != nil {
		s.internalError(w, r, err)
		return
	}
	tags := make(map[string]int64, len(counts))
	for _, tc := range counts {
		tags[tc.Tag] = tc.Count
	}
	writeJSON(w, http.StatusOK, map[string]any{"notes": total, "tags": tags})
}

func (s *Server) tags(w http.ResponseWriter, r *http.Request) {
	counts, err := s.store.TagCounts(r.Context())
	if err != nil {
		s.internalError(w, r, err)
		return
	}
	writeJSON(w, http.StatusOK, map[string]any{"tags": counts})
}

func (s *Server) readNoteInput(w http.ResponseWriter, r *http.Request) (noteInput, bool) {
	data, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	if err != nil {
		var tooBig *http.MaxBytesError
		if errors.As(err, &tooBig) {
			writeError(w, http.StatusRequestEntityTooLarge, "request body too large")
		} else {
			writeError(w, http.StatusBadRequest, "could not read request body")
		}
		return noteInput{}, false
	}
	in, err := parseNoteInput(data)
	if err != nil {
		writeError(w, http.StatusBadRequest, err.Error())
		return noteInput{}, false
	}
	return in, true
}

func noteID(w http.ResponseWriter, r *http.Request) (int64, bool) {
	id, ok := parsePositiveID(strings.TrimPrefix(r.URL.Path, "/notes/"))
	if !ok {
		writeError(w, http.StatusNotFound, "note not found")
	}
	return id, ok
}

func (s *Server) storeError(w http.ResponseWriter, r *http.Request, err error) {
	if errors.Is(err, store.ErrNotFound) {
		writeError(w, http.StatusNotFound, "note not found")
		return
	}
	s.internalError(w, r, err)
}

func (s *Server) internalError(w http.ResponseWriter, r *http.Request, err error) {
	s.log.Error("request failed", "method", r.Method, "path", r.URL.Path, "err", err)
	writeError(w, http.StatusInternalServerError, "internal server error")
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	data, err := json.Marshal(v)
	if err != nil {
		http.Error(w, `{"error":"internal server error"}`, http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write(append(data, '\n'))
}

package server

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"notes/internal/store"
)

func newTestServer(t *testing.T, dbPath string) *httptest.Server {
	t.Helper()
	st, err := store.Open(context.Background(), dbPath)
	if err != nil {
		t.Fatal(err)
	}
	ts := httptest.NewServer(New(st, slog.New(slog.DiscardHandler)))
	t.Cleanup(func() {
		ts.Close()
		st.Close()
	})
	return ts
}

func do(t *testing.T, ts *httptest.Server, method, path, body string) (int, string) {
	t.Helper()
	var rd io.Reader
	if body != "" {
		rd = strings.NewReader(body)
	}
	req, err := http.NewRequest(method, ts.URL+path, rd)
	if err != nil {
		t.Fatal(err)
	}
	res, err := ts.Client().Do(req)
	if err != nil {
		t.Fatal(err)
	}
	defer res.Body.Close()
	data, err := io.ReadAll(res.Body)
	if err != nil {
		t.Fatal(err)
	}
	return res.StatusCode, strings.TrimSpace(string(data))
}

func TestAPI(t *testing.T) {
	ts := newTestServer(t, filepath.Join(t.TempDir(), "notes.db"))

	steps := []struct {
		method, path, body string
		status             int
		want               string // exact JSON, or "" to skip
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/notes", `{"title":"  Hello World ","tags":["b","a","b"]}`, 201, `{"id":1,"title":"Hello World","body":"","tags":["a","b"]}`},
		{"POST", "/notes", `{"title":"second","body":"50% off_now"}`, 201, `{"id":2,"title":"second","body":"50% off_now","tags":[]}`},
		{"POST", "/notes", `{"title":"third","body":"x","tags":["a"]}`, 201, ""},
		{"GET", "/notes?q=hello", "", 200, `{"notes":[{"id":1,"title":"Hello World","body":"","tags":["a","b"]}]}`},
		{"GET", "/notes?q=%25", "", 200, `{"notes":[{"id":2,"title":"second","body":"50% off_now","tags":[]}]}`},
		{"GET", "/notes?q=f_n", "", 200, `{"notes":[{"id":2,"title":"second","body":"50% off_now","tags":[]}]}`},
		{"GET", "/notes?q=f_x", "", 200, `{"notes":[]}`},
		{"GET", "/notes?tag=a&after=1", "", 200, `{"notes":[{"id":3,"title":"third","body":"x","tags":["a"]}]}`},
		{"GET", "/notes?limit=101", "", 400, ""},
		{"GET", "/notes?limit=abc", "", 400, ""},
		{"GET", "/notes?after=", "", 400, ""},
		{"GET", "/notes?after=1.5", "", 400, ""},
		{"GET", "/tags", "", 200, `{"tags":[{"tag":"a","count":2},{"tag":"b","count":1}]}`},
		{"DELETE", "/notes/1", "", 204, ""},
		{"GET", "/stats", "", 200, `{"notes":2,"tags":{"a":1}}`},
		{"DELETE", "/notes", "", 405, ""},
		{"PATCH", "/notes/1", "", 405, ""},
		{"GET", "/notes/", "", 404, ""},
		{"GET", "/notes/-1", "", 404, ""},
		{"GET", "/notes/99999999999999999999", "", 404, ""},
		{"POST", "/notes", `null`, 400, ""},
		{"POST", "/notes", `{"title":"a"} {}`, 400, ""},
		{"POST", "/notes", `{"title":null}`, 400, ""},
		{"POST", "/notes", `{"title":5}`, 400, ""},
		{"POST", "/notes", `{"title":"a","body":null}`, 400, ""},
		{"POST", "/notes", `{"title":"a","tags":"x"}`, 400, ""},
		{"POST", "/notes", `{"title":"a","tags":[1]}`, 400, ""},
		{"POST", "/notes", `{"title":"a","tags":[""]}`, 400, ""},
		{"POST", "/notes", `{"title":"a","tags":["` + strings.Repeat("x", 33) + `"]}`, 400, ""},
		{"POST", "/notes", `{"title":"` + strings.Repeat("é", 201) + `"}`, 400, ""},
		{"POST", "/notes", `{"title":"` + strings.Repeat("é", 200) + `"}`, 201, ""},
		{"PUT", "/notes/2", `{"title":"new"}`, 200, `{"id":2,"title":"new","body":"","tags":[]}`},
		{"PUT", "/notes/1", `{"title":"gone"}`, 404, ""},
		{"PUT", "/notes/2", `{"title":""}`, 400, ""},
	}
	for _, s := range steps {
		status, body := do(t, ts, s.method, s.path, s.body)
		if status != s.status {
			t.Errorf("%s %s %s: status %d, want %d (body %s)", s.method, s.path, s.body, status, s.status, body)
			continue
		}
		if s.want != "" && body != s.want {
			t.Errorf("%s %s: body %s, want %s", s.method, s.path, body, s.want)
		}
	}
}

func TestPersistenceAndIDsNotReused(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "notes.db")
	ts := newTestServer(t, dbPath)
	do(t, ts, "POST", "/notes", `{"title":"a"}`)
	do(t, ts, "POST", "/notes", `{"title":"b"}`)
	do(t, ts, "DELETE", "/notes/2", "")

	ts2 := newTestServer(t, dbPath)
	status, body := do(t, ts2, "POST", "/notes", `{"title":"c"}`)
	if status != 201 || body != `{"id":3,"title":"c","body":"","tags":[]}` {
		t.Fatalf("got %d %s", status, body)
	}
}

func TestConcurrentCreates(t *testing.T) {
	ts := newTestServer(t, filepath.Join(t.TempDir(), "notes.db"))
	const n = 50
	var wg sync.WaitGroup
	for i := range n {
		wg.Go(func() {
			status, body := do(t, ts, "POST", "/notes", fmt.Sprintf(`{"title":"n%d","tags":["t"]}`, i))
			if status != 201 {
				t.Errorf("status %d: %s", status, body)
			}
		})
	}
	wg.Wait()
	_, body := do(t, ts, "GET", "/stats", "")
	var got struct {
		Notes int            `json:"notes"`
		Tags  map[string]int `json:"tags"`
	}
	if err := json.Unmarshal([]byte(body), &got); err != nil {
		t.Fatal(err)
	}
	if got.Notes != n || got.Tags["t"] != n {
		t.Fatalf("stats %s", body)
	}
}

package server

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"slices"
	"strconv"
	"strings"
	"unicode/utf8"
)

const (
	maxTitleLen = 200
	maxTagLen   = 32
)

// noteInput is a validated create/replace request.
type noteInput struct {
	Title string
	Body  string
	Tags  []string
}

// parseNoteInput decodes and validates a note request body.
func parseNoteInput(data []byte) (noteInput, error) {
	var fields map[string]json.RawMessage
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&fields); err != nil {
		return noteInput{}, errors.New("request body must be a JSON object")
	}
	if fields == nil {
		return noteInput{}, errors.New("request body must be a JSON object")
	}
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		return noteInput{}, errors.New("request body must be a single JSON object")
	}

	var in noteInput

	rawTitle, ok := fields["title"]
	if !ok {
		return noteInput{}, errors.New("title is required")
	}
	title, ok := decodeString(rawTitle)
	if !ok {
		return noteInput{}, errors.New("title must be a string")
	}
	in.Title = strings.TrimSpace(title)
	if n := utf8.RuneCountInString(in.Title); n < 1 || n > maxTitleLen {
		return noteInput{}, fmt.Errorf("title must be 1-%d characters", maxTitleLen)
	}

	if raw, ok := fields["body"]; ok {
		body, ok := decodeString(raw)
		if !ok {
			return noteInput{}, errors.New("body must be a string")
		}
		in.Body = body
	}

	in.Tags = []string{}
	if raw, ok := fields["tags"]; ok {
		tags, err := decodeTags(raw)
		if err != nil {
			return noteInput{}, err
		}
		in.Tags = tags
	}
	return in, nil
}

// decodeString decodes raw as a JSON string; null and other types are rejected.
func decodeString(raw json.RawMessage) (string, bool) {
	raw = bytes.TrimSpace(raw)
	if len(raw) == 0 || raw[0] != '"' {
		return "", false
	}
	var s string
	if err := json.Unmarshal(raw, &s); err != nil {
		return "", false
	}
	return s, true
}

func decodeTags(raw json.RawMessage) ([]string, error) {
	raw = bytes.TrimSpace(raw)
	var items []json.RawMessage
	if len(raw) == 0 || raw[0] != '[' || json.Unmarshal(raw, &items) != nil {
		return nil, errors.New("tags must be an array of strings")
	}
	tags := make([]string, 0, len(items))
	for _, item := range items {
		tag, ok := decodeString(item)
		if !ok {
			return nil, errors.New("tags must be an array of strings")
		}
		if !validTag(tag) {
			return nil, fmt.Errorf("invalid tag %q: must be 1-%d characters from a-z, 0-9 and -", tag, maxTagLen)
		}
		tags = append(tags, tag)
	}
	slices.Sort(tags)
	return slices.Compact(tags), nil
}

func validTag(tag string) bool {
	if len(tag) < 1 || len(tag) > maxTagLen {
		return false
	}
	for i := 0; i < len(tag); i++ {
		c := tag[i]
		if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '-') {
			return false
		}
	}
	return true
}

// parsePositiveID parses a path segment as a note id: a positive decimal integer.
func parsePositiveID(s string) (int64, bool) {
	if s == "" || strings.Trim(s, "0123456789") != "" {
		return 0, false
	}
	id, err := strconv.ParseInt(s, 10, 64)
	return id, err == nil && id > 0
}

// parseInt parses an optionally signed decimal integer query parameter.
func parseInt(s string) (int64, bool) {
	digits := strings.TrimPrefix(s, "-")
	if digits == "" || strings.Trim(digits, "0123456789") != "" {
		return 0, false
	}
	n, err := strconv.ParseInt(s, 10, 64)
	return n, err == nil
}

// Package store persists notes in a SQLite database.
package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"net/url"
	"slices"
	"strings"

	_ "modernc.org/sqlite" // registers the "sqlite" driver
)

// ErrNotFound is returned when a note does not exist.
var ErrNotFound = errors.New("note not found")

// Note is a stored note.
type Note struct {
	ID    int64    `json:"id"`
	Title string   `json:"title"`
	Body  string   `json:"body"`
	Tags  []string `json:"tags"`
}

// TagCount is the number of notes carrying a tag.
type TagCount struct {
	Tag   string `json:"tag"`
	Count int64  `json:"count"`
}

// ListFilter selects notes for List. Zero values mean "no filter".
type ListFilter struct {
	Tag   string
	Query string
	After int64
	Limit int
}

// Store is a SQLite-backed notes store, safe for concurrent use.
type Store struct {
	db *sql.DB
}

const schema = `
CREATE TABLE IF NOT EXISTS notes (
	id    INTEGER PRIMARY KEY AUTOINCREMENT,
	title TEXT NOT NULL,
	body  TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS note_tags (
	note_id INTEGER NOT NULL REFERENCES notes(id) ON DELETE CASCADE,
	tag     TEXT NOT NULL,
	PRIMARY KEY (note_id, tag)
) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS note_tags_tag ON note_tags(tag, note_id);
`

// Open opens (creating if needed) the database at path and ensures the schema exists.
func Open(ctx context.Context, path string) (*Store, error) {
	q := url.Values{}
	q.Add("_pragma", "busy_timeout(10000)")
	q.Add("_pragma", "journal_mode(WAL)")
	q.Add("_pragma", "synchronous(NORMAL)")
	q.Add("_pragma", "foreign_keys(ON)")
	q.Set("_txlock", "immediate")
	dsn := "file:" + path + "?" + q.Encode()

	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		return nil, fmt.Errorf("open database: %w", err)
	}
	if _, err := db.ExecContext(ctx, schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("create schema: %w", err)
	}
	return &Store{db: db}, nil
}

// Close closes the database.
func (s *Store) Close() error { return s.db.Close() }

// Create inserts a new note and returns it with its assigned id.
func (s *Store) Create(ctx context.Context, title, body string, tags []string) (Note, error) {
	var n Note
	err := s.inTx(ctx, func(tx *sql.Tx) error {
		res, err := tx.ExecContext(ctx, `INSERT INTO notes (title, body) VALUES (?, ?)`, title, body)
		if err != nil {
			return err
		}
		id, err := res.LastInsertId()
		if err != nil {
			return err
		}
		if err := insertTags(ctx, tx, id, tags); err != nil {
			return err
		}
		n = Note{ID: id, Title: title, Body: body, Tags: tags}
		return nil
	})
	return n, err
}

// Update replaces the content of an existing note.
func (s *Store) Update(ctx context.Context, id int64, title, body string, tags []string) (Note, error) {
	var n Note
	err := s.inTx(ctx, func(tx *sql.Tx) error {
		res, err := tx.ExecContext(ctx, `UPDATE notes SET title = ?, body = ? WHERE id = ?`, title, body, id)
		if err != nil {
			return err
		}
		if affected, err := res.RowsAffected(); err != nil {
			return err
		} else if affected == 0 {
			return ErrNotFound
		}
		if _, err := tx.ExecContext(ctx, `DELETE FROM note_tags WHERE note_id = ?`, id); err != nil {
			return err
		}
		if err := insertTags(ctx, tx, id, tags); err != nil {
			return err
		}
		n = Note{ID: id, Title: title, Body: body, Tags: tags}
		return nil
	})
	return n, err
}

// Delete removes a note and its tags.
func (s *Store) Delete(ctx context.Context, id int64) error {
	return s.inTx(ctx, func(tx *sql.Tx) error {
		if _, err := tx.ExecContext(ctx, `DELETE FROM note_tags WHERE note_id = ?`, id); err != nil {
			return err
		}
		res, err := tx.ExecContext(ctx, `DELETE FROM notes WHERE id = ?`, id)
		if err != nil {
			return err
		}
		if affected, err := res.RowsAffected(); err != nil {
			return err
		} else if affected == 0 {
			return ErrNotFound
		}
		return nil
	})
}

// Get returns the note with the given id.
func (s *Store) Get(ctx context.Context, id int64) (Note, error) {
	notes, err := s.queryNotes(ctx, `SELECT id, title, body FROM notes WHERE id = ?`, id)
	if err != nil {
		return Note{}, err
	}
	if len(notes) == 0 {
		return Note{}, ErrNotFound
	}
	return notes[0], nil
}

// List returns notes matching f, ordered by id ascending.
func (s *Store) List(ctx context.Context, f ListFilter) ([]Note, error) {
	var (
		where []string
		args  []any
	)
	if f.After != 0 {
		where = append(where, "n.id > ?")
		args = append(args, f.After)
	}
	if f.Tag != "" {
		where = append(where, "EXISTS (SELECT 1 FROM note_tags t WHERE t.note_id = n.id AND t.tag = ?)")
		args = append(args, f.Tag)
	}
	if f.Query != "" {
		// SQLite's LIKE is case-insensitive for ASCII characters only, which is exactly what we want.
		where = append(where, `(n.title LIKE ? ESCAPE '\' OR n.body LIKE ? ESCAPE '\')`)
		pattern := "%" + escapeLike(f.Query) + "%"
		args = append(args, pattern, pattern)
	}
	query := "SELECT n.id, n.title, n.body FROM notes n"
	if len(where) > 0 {
		query += " WHERE " + strings.Join(where, " AND ")
	}
	query += " ORDER BY n.id"
	if f.Limit > 0 {
		query += " LIMIT ?"
		args = append(args, f.Limit)
	}
	return s.queryNotes(ctx, query, args...)
}

// TagCounts returns every tag in use with its note count, ordered by count
// descending, then tag ascending.
func (s *Store) TagCounts(ctx context.Context) ([]TagCount, error) {
	_, counts, err := s.stats(ctx)
	return counts, err
}

// Stats returns the number of notes and the per-tag note counts, taken from
// one consistent snapshot. Tags are ordered as in TagCounts.
func (s *Store) Stats(ctx context.Context) (int64, []TagCount, error) {
	return s.stats(ctx)
}

func (s *Store) stats(ctx context.Context) (int64, []TagCount, error) {
	// A single statement reads from a single snapshot, so the note count and
	// the tag counts always agree. The first row (NULL tag) is the note count.
	rows, err := s.db.QueryContext(ctx, `
		SELECT NULL, COUNT(*), 0 FROM notes
		UNION ALL
		SELECT * FROM (SELECT tag, COUNT(*) AS c, 1 FROM note_tags GROUP BY tag)
		ORDER BY 3, 2 DESC, 1 ASC`)
	if err != nil {
		return 0, nil, err
	}
	defer rows.Close()
	var (
		total  int64
		counts = []TagCount{}
	)
	for rows.Next() {
		var (
			tag   sql.NullString
			count int64
			kind  int
		)
		if err := rows.Scan(&tag, &count, &kind); err != nil {
			return 0, nil, err
		}
		if kind == 0 {
			total = count
			continue
		}
		counts = append(counts, TagCount{Tag: tag.String, Count: count})
	}
	return total, counts, rows.Err()
}

func (s *Store) queryNotes(ctx context.Context, query string, args ...any) ([]Note, error) {
	// Fetching notes and their tags in one statement keeps the result consistent
	// without an explicit transaction. Tags never contain commas, so group_concat is safe.
	full := `SELECT q.id, q.title, q.body,
		(SELECT group_concat(tag, ',') FROM note_tags WHERE note_id = q.id)
		FROM (` + query + `) q ORDER BY q.id`
	rows, err := s.db.QueryContext(ctx, full, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	notes := []Note{}
	for rows.Next() {
		var (
			n    Note
			tags sql.NullString
		)
		if err := rows.Scan(&n.ID, &n.Title, &n.Body, &tags); err != nil {
			return nil, err
		}
		n.Tags = []string{}
		if tags.Valid && tags.String != "" {
			n.Tags = strings.Split(tags.String, ",")
			slices.Sort(n.Tags)
		}
		notes = append(notes, n)
	}
	return notes, rows.Err()
}

func (s *Store) inTx(ctx context.Context, fn func(*sql.Tx) error) error {
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	if err := fn(tx); err != nil {
		tx.Rollback()
		return err
	}
	return tx.Commit()
}

func insertTags(ctx context.Context, tx *sql.Tx, id int64, tags []string) error {
	if len(tags) == 0 {
		return nil
	}
	stmt, err := tx.PrepareContext(ctx, `INSERT OR IGNORE INTO note_tags (note_id, tag) VALUES (?, ?)`)
	if err != nil {
		return err
	}
	defer stmt.Close()
	for _, t := range tags {
		if _, err := stmt.ExecContext(ctx, id, t); err != nil {
			return err
		}
	}
	return nil
}

func escapeLike(s string) string {
	r := strings.NewReplacer(`\`, `\\`, `%`, `\%`, `_`, `\_`)
	return r.Replace(s)
}

// Command app serves a small notes store backed by SQLite.
//
// Usage: app <port>, with the database path in the NOTES_DB environment variable.
package main

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"notes/internal/server"
	"notes/internal/store"
)

func main() {
	log := slog.New(slog.NewTextHandler(os.Stderr, nil))
	if err := run(log, os.Args[1:]); err != nil {
		log.Error("fatal", "err", err)
		os.Exit(1)
	}
}

func run(log *slog.Logger, args []string) error {
	if len(args) != 1 {
		return errors.New("usage: app <port>")
	}
	port, err := strconv.Atoi(args[0])
	if err != nil || port < 0 || port > 65535 {
		return fmt.Errorf("invalid port %q", args[0])
	}
	dbPath := os.Getenv("NOTES_DB")
	if dbPath == "" {
		return errors.New("NOTES_DB is not set")
	}

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	st, err := store.Open(ctx, dbPath)
	if err != nil {
		return err
	}
	defer st.Close()

	ln, err := net.Listen("tcp", net.JoinHostPort("127.0.0.1", strconv.Itoa(port)))
	if err != nil {
		return err
	}
	srv := &http.Server{
		Handler:           server.New(st, log),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       60 * time.Second,
		WriteTimeout:      60 * time.Second,
		IdleTimeout:       120 * time.Second,
	}

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()
	log.Info("listening", "addr", ln.Addr().String(), "db", dbPath)

	select {
	case err := <-errc:
		return err
	case <-ctx.Done():
	}
	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	return srv.Shutdown(shutdownCtx)
}
